const CURRENCY_UNITS=ECONOMY.bank.units,CURRENCY_NAMES={coins:'gold',tickets:'Pushcat tickets',rubies:'rubies'},CURRENCY_LIMIT=Number.MAX_VALUE,BANK_SLIDER_STEPS=1000;
function bankMaxLots(from,to){return game.bankMaxLots(from,to);}
function updateBankControls(){const from=$('bank-from').value,to=$('bank-to').value,max=bankMaxLots(from,to),amount=$('bank-amount'),slider=$('bank-slider');amount.max=String(max);$('bank-max').textContent=`Maximum available: ${fmt(max*CURRENCY_UNITS[from])} ${CURRENCY_NAMES[from]} (${fmt(max)} bundles)`;const lots=Math.max(0,Math.min(max,Math.floor(Number(amount.value)||0)));amount.value=String(lots);slider.value=max?String(Math.round(lots/max*BANK_SLIDER_STEPS)):'0';$('bank-rate').textContent=`One bundle: ${fmt(CURRENCY_UNITS[from])} ${CURRENCY_NAMES[from]} → ${fmt(CURRENCY_UNITS[to])} ${CURRENCY_NAMES[to]}.`;$('bank-preview').textContent=lots?`You pay ${fmt(lots*CURRENCY_UNITS[from])} ${CURRENCY_NAMES[from]} and receive ${fmt(lots*CURRENCY_UNITS[to])} ${CURRENCY_NAMES[to]}.`:'Choose an amount to see the exchange.';$('bank-exchange').disabled=lots<1;}
function renderBank(){const from=$('bank-from'),to=$('bank-to');if(from.value===to.value)to.value=['tickets','rubies'].find(currency=>currency!==from.value);from.onchange=()=>{if(from.value===to.value)to.value=['tickets','rubies'].find(currency=>currency!==from.value);$('bank-amount').value='0';updateBankControls();};to.onchange=()=>{if(from.value===to.value)from.value=['tickets','rubies'].find(currency=>currency!==to.value);$('bank-amount').value='0';updateBankControls();};$('bank-amount').oninput=updateBankControls;$('bank-slider').oninput=()=>{const max=bankMaxLots(from.value,to.value);$('bank-amount').value=String(Math.round(max*Number($('bank-slider').value)/BANK_SLIDER_STEPS));updateBankControls();};$('bank-exchange').onclick=()=>{const source=from.value,target=to.value,lots=Math.floor(Number($('bank-amount').value)||0);if(!game.exchange(source,target,lots))return;save(true);render();$('bank-amount').value='0';updateBankControls();notice(`${fmt(lots*CURRENCY_UNITS[source])} ${CURRENCY_NAMES[source]} exchanged for ${fmt(lots*CURRENCY_UNITS[target])} ${CURRENCY_NAMES[target]}.`,'success');};updateBankControls();}
function fmt(x){if(!Number.isFinite(x))return String(x);const sign=x<0?'-':'',n=Math.abs(x);if(n<1e6)return Math.floor(x).toLocaleString('en-US');const units=['K','M','B','T','Qa','Qi','Sx','Sp','Oc','No','Dc','Ud','Dd','Td','Qad','Qid','Sxd','Spd','Ocd','Nod','Vg','Uvg','Dvg','Tvg','Qavg','Qivg','Sxvg','Spvg','Ocvg','Novg','Tg'];let group=Math.floor(Math.log10(n)/3),index=group-1;if(index>=units.length)return x.toExponential(3);let scaled=n/10**(group*3);const digits=scaled<100?2:scaled<1000?1:0;let rounded=Number(scaled.toFixed(digits));if(rounded>=1000&&index+1<units.length){rounded/=1000;index++;}return`${sign}${rounded} ${units[index]}`;}
