const upgradeRows=[['tier0','Life Potion Materials'],['tier1','Mana Potion Materials'],['tier2','Stamina Potion Materials'],['speed','Material Emission'],['luck','Enhancement Success Rate'],['price','Selling Price']];
const upgradeNodes=new Map();
function renderUpgrades(){const s=game.state,key=JSON.stringify([s.coins,s.tiers,s.luck,s.price,s.speed,s.masteryStars,s.metrics.enhancementsSucceeded,s.metrics.brewsStarted]);if(renderUpgrades.state===s&&renderUpgrades.key===key)return;renderUpgrades.state=s;renderUpgrades.key=key;const box=$('upgrades');for(const[key,title]of upgradeRows){let nodes=upgradeNodes.get(key);if(!nodes){const row=document.createElement('div');row.className='upgrade';const copy=document.createElement('div'),heading=document.createElement('h3'),desc=document.createElement('p'),costLine=document.createElement('div'),coin=document.createElement('img'),cost=document.createElement('span'),progress=document.createElement('div'),button=document.createElement('button'),level=document.createElement('span'),action=document.createElement('span');costLine.className='upgrade-cost';coin.src=art('Coin.png');coin.alt='';coin.setAttribute('aria-hidden','true');costLine.append(coin,cost);button.classList.add('upgrade-action');level.className='upgrade-level';action.className='upgrade-label';button.append(level,action);button.dataset.upgrade=key;button.onclick=()=>{if(game.buy(key)){notice(`${title} upgraded.`,'success');save(true);render();updateBeltLabels();}};copy.append(heading,desc,costLine,progress);row.append(copy,button);box.append(row);nodes={heading,desc,costLine,cost,progress,button,level,action};upgradeNodes.set(key,nodes);}
 const u=game.upgradeInfo(key),max=u.level>=u.max,{heading,desc,costLine,cost,progress,button,level,action}=nodes;let description;
 if(key.startsWith('tier')){const f=Number(key.slice(4));description=max?'All material tiers unlocked.':`Next: ${FAMILIES[f].materials[u.level+1].name}`;}else if(key==='speed')description=`More materials at the same belt speed · ${(1+u.level*ECONOMY.upgrades.speed.bonusPerLevel).toFixed(2)}× density. Also increases special-drop opportunities.`;else if(key==='luck')description=`+${(game.state.luck*ECONOMY.upgrades.luck.bonusPerLevel*100).toFixed(4).replace(/0+$/,'').replace(/\.$/,'')} percentage points`;else description=`+${game.state.price*ECONOMY.upgrades.price.bonusPerLevel*100}% to potion sales`;
 setText(heading,title);setText(desc,description);costLine.hidden=max;setText(cost,`${fmt(u.cost)} coins`);progress.hidden=max||!u.requiredMastery;setText(progress,`${u.mastered} / ${u.requiredMastery} ${key.startsWith('tier')?FAMILIES[Number(key.slice(4))].label:''} potions mastered`);setText(level,`Level ${u.displayLevel}`);setText(action,max?'Max':u.locked?'Mastery locked':'Upgrade');button.classList.toggle('maxed',max);button.disabled=max||u.locked||game.state.coins<u.cost;const label=max?title+' maximum':u.locked?`Master ${u.requiredMastery} ${FAMILIES[Number(key.slice(4))].label} potions to unlock this upgrade`:`Buy ${title} for ${u.cost} coins`;if(button.getAttribute('aria-label')!==label)button.setAttribute('aria-label',label);
}renderUpgradeSummary();}
function renderUpgradeSummary(){const complete=upgradeRows.every(([key])=>{const u=game.upgradeInfo(key);return u.level>=u.max;}),details=$('completed-upgrades'),box=$('upgrades'),goal=$('upgrade-goal');details.hidden=!complete;goal.hidden=!complete;if(complete){if(box.parentElement!==details)details.append(box);const next=FAMILIES.flatMap((family,f)=>family.recipes.slice(0,game.state.tiers[f]+1).map((recipe,t)=>({recipe,f,t}))).find(({recipe,f,t})=>(game.state.metrics.recipes[f+'-'+t]?.highestLevel||0)<recipe.max_level);if(next){const{recipe,f,t}=next,level=game.state.metrics.recipes[f+'-'+t]?.highestLevel||0;setText($('upgrade-goal-name'),recipe.name);setText($('upgrade-goal-progress'),`Reach level ${recipe.max_level} · best ${level} / ${recipe.max_level}`);setText($('upgrade-goal-title'),ACHIEVEMENT_LORE.entries[f+'-'+t].title);}else{setText($('upgrade-goal-name'),'Every potion mastered');setText($('upgrade-goal-progress'),'All 75 potion achievements earned.');setText($('upgrade-goal-title'),'Your collection is complete.');}}else if(box.parentElement===details){details.before(box);details.open=false;}}
