function renderCostumeShop(){
 const character=window.brewerCharacter||'Pio',entries=COSTUMES.entries.filter(c=>c.character===character),grid=$('costume-grid'),owned=new Set(game.state.costumes);grid.replaceChildren();
 $('costume-shop-balance').textContent=`You have ${fmt(game.state.tickets)} tickets · ${entries.filter(c=>owned.has(c.id)).length} / ${entries.length} ${character} costumes owned.`;
 for(const animated of [true,false]){
  const sectionEntries=entries.filter(c=>(c.live2d&&!EVENT_SKINS.has(c.id))===animated);if(!sectionEntries.length)continue;
  const section=document.createElement('section'),title=document.createElement('h3'),note=document.createElement('p'),cards=document.createElement('div');
  section.className='costume-section';title.textContent=animated?'Available':'Unavailable';note.className='small muted';note.textContent=animated?`Live2D costumes · ${ECONOMY.costumes.ticketPrice} each.`:'Event skins are redeemed in Events. Static costumes are free.';cards.className='costume-grid';
  for(const costume of sectionEntries){
   const card=document.createElement('section'),image=document.createElement('img'),heading=document.createElement('h3'),status=document.createElement('p'),button=document.createElement('button'),isOwned=owned.has(costume.id),equipped=game.state.activeCostumeId===costume.id,eventSkin=EVENT_SKINS.has(costume.id),price=costume.live2d&&!costume.free?ECONOMY.costumes.ticketPrice:0;
   card.className='costume-card';image.src=art(costume.id);image.alt=costume.name;image.loading='lazy';heading.textContent=costume.name;status.textContent=equipped?'Wearing':isOwned?'Owned':eventSkin?EVENTS.find(event=>event.skins.includes(costume.id)).name:!costume.live2d?'Free · static image':'';
   button.textContent=equipped?'Wearing':eventSkin&&!isOwned?'Event skin':!costume.live2d?'Wear · free':isOwned?'Wear':'';button.className=isOwned||!costume.live2d||eventSkin?'':'primary';button.disabled=equipped||(!isOwned&&(eventSkin||game.state.tickets<price));
   if(!isOwned&&costume.live2d&&!eventSkin){const ticket=document.createElement('img');ticket.src=art('Nyan-Ticket.png');ticket.alt='';ticket.className='costume-ticket-icon';status.append(document.createTextNode(`${price} `),ticket);button.textContent='Buy';}
   button.onclick=()=>{const success=isOwned?game.equipCostume(costume.id):game.buyCostume(costume.id);if(!success)return;try{localStorage.setItem('pmg-costume-'+character,costume.id);}catch{}save(true);render();renderCostumeShop();notice(`${costume.name} equipped.`,'success');};card.append(image,heading,status,button);if(eventSkin&&isOwned){const marker=document.createElement('button');marker.type='button';marker.textContent='Event skin';marker.disabled=true;card.append(marker);}cards.append(card);
  }
  section.append(title,note,cards);grid.append(section);
 }
}

function renderPowerups(){for(const[key,id,label,verb]of [['protection','protection-indicator','Protection','Consumed automatically when an enhancement fails.'],['enhancement','enhancement-indicator','Enhancement boost','One charge is used on each enhancement attempt.'],['selling','selling-indicator','Sale boost','One charge is used on a potion sale.']]){const indicator=$(id),count=$(id+'-count'),amount=game.state.powerups[key];indicator.hidden=amount<1;indicator.title=verb;indicator.setAttribute('aria-label',`${amount} ${label.toLowerCase()} ${amount===1?'charge':'charges'}`);setText(count,amount);}}
let travelerSnapshot='';
function readyQuestIndex(){return game.state.travelers.findIndex((_,index)=>game.canDeliver(index));}
function updateSellAction(){const index=readyQuestIndex(),button=$('sell');button.firstChild.textContent=index>=0?'Advance quest ':'Sell potion ';button.title=index>=0?`Give this potion to ${TRAVELERS[index].name}`:'Sell the current potion';$('selling-indicator').hidden=index>=0||game.state.powerups.selling<1;}
function updateQuestButtons(){updateSellAction();const index=game.state.travelers.findIndex(t=>t.phase==='active');if(index>=0){const button=$('travelers').querySelector('[data-phase="active"] button');if(button)button.disabled=!game.canDeliver(index);}}

function visitorLine(traveler,state,q,phase=state.phase){const character=COSTUMES.entries.find(c=>c.id===game.state.activeCostumeId)?.character||'Pio',documented=VISITOR_DIALOGUE.documented?.[traveler.id],lines=documented?.[character]?.[phase]||documented?.[phase];if(!lines)return VISITOR_DIALOGUE.entries[traveler.id]?.[phase]||'';const seed=state.leaveAt||state.deadline||state.readyAt||0;return lines[Math.floor(seed/1000)%lines.length].replaceAll('{level}',String((q?.level??0)+1)).replaceAll('{potion}',q?FAMILIES[q.family].recipes[q.tier].name:'potion');}
