 const q=game.questRequirement(i),card=document.createElement('div');card.className='card traveler';card.dataset.phase=state.phase;
 const im=document.createElement('img');let portrait=traveler.portrait;if(['charlotte','daisy'].includes(traveler.id)){const prefix=traveler.name;if(state.phase==='failed')portrait=prefix+'PortraitDisappointed.png';else if(['returning','complete'].includes(state.phase))portrait=prefix+'PortraitHappy.png';}im.src=art(portrait);im.alt=traveler.name;
 const body=document.createElement('div');body.className='traveler-body';const heading=document.createElement('h3');heading.textContent=traveler.name;
 const speech=document.createElement('p');speech.className='speech';speech.textContent=visitorLine(traveler,state,q);
 const description=document.createElement('p');if(q){const xp=game.experienceFor(q.family,q.tier);description.className='quest-order';const label=document.createElement('span'),name=document.createElement('strong'),level=document.createElement('span');label.className='small muted';label.textContent='Required potion';name.textContent=FAMILIES[q.family].recipes[q.tier].name;level.textContent=`Level ${q.level+1} or higher · ${xp}${game.experienceIsEstimated(q.family,q.tier)?' estimated':''} EXP`;description.append(label,name,level);const image=document.createElement('img');image.src=art(FAMILIES[q.family].recipes[q.tier].image);image.alt=FAMILIES[q.family].recipes[q.tier].name;description.append(image);}
 const progress=document.createElement('p');progress.className='small muted';progress.textContent=state.level>=12?`Level 12 · ${fmt(state.exp)} EXP · max level`:`Level ${state.level} · ${fmt(state.exp)} / ${fmt(LEVEL_EXP[state.level])} EXP`;
 const reward=document.createElement('p');reward.className='quest-reward';reward.textContent='Reward: '+visitorRewardText(traveler,state);
 const timer=document.createElement('p');timer.dataset.questTimer=i;timer.className=state.phase==='active'?'timer quest-deadline':'timer';
 const actions=document.createElement('div');actions.className='quest-actions';
 function button(label,action,disabled=false){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;if(label==='Accept quest'||label==='Give potion')b.className='primary';b.onclick=()=>{if(action()){save(true);render();updateBeltLabels();}};actions.append(b);}
 if(state.phase==='offer'){timer.textContent=questTimerText(state);button('Accept quest',()=>game.acceptQuest(i));button('Not now',()=>game.dismissVisitor(i));}
 if(state.phase==='active'){timer.textContent=questTimerText(state);button('Give potion',()=>{if(!game.deliver(i))return false;notice('Potion delivered. '+traveler.name+' will return with your reward in '+ECONOMY.visitors.rewardDelayMs/1000+' seconds.','success');return true;},!game.canDeliver(i));}
 if(state.phase==='returning')timer.textContent=questTimerText(state);
 if(state.phase==='failed'){timer.textContent=questTimerText(state);button('Say goodbye',()=>game.dismissVisitor(i));}
 if(state.phase==='complete'){timer.textContent=questTimerText(state);button('Say goodbye',()=>game.dismissVisitor(i));}
