function requestStatusText(){const active=game.state.request;if(!active)return'';return`${TRAVELERS[active.travelerIndex].name} is away on ${REQUESTS.find(r=>r.id===active.requestId).name}. Time left: ${duration(Math.max(0,active.readyAt-Date.now()))}.`;}
function updateRequestIndicator(){const el=$('request-current'),active=game.state.request;el.hidden=!active;setText(el,active?requestStatusText():'');}
function visitorRewardText(t,state){const parts=[],r=state.rewardBoost;if(r)parts.push(`${r.amount} ${r.type==='protection'?'failure protection':r.type==='enhancement'?'enhancement bonus':'selling bonus'} ${r.amount===1?'charge':'charges'}`);if(state.rewardTickets)parts.push(`${state.rewardTickets} Pushcat tickets`);if(state.rewardRubies)parts.push(`${state.rewardRubies} ${state.rewardRubies===1?'ruby':'rubies'}`);if(state.rewardFairyId)parts.push(FAIRIES.find(f=>f.id===state.rewardFairyId)?.name||'fairy');return parts.join(' · ')||'No pending reward';}
function rewardArrivalText(t){const state=game.state.travelers[TRAVELERS.findIndex(v=>v.id===t.id)];return `${t.name} returned: ${visitorRewardText(t,state)}.`;}

