function renderAchievements(){const filters=$('achievement-filters'),grid=$('achievement-grid');filters.replaceChildren();grid.replaceChildren();const earned=masteredPotionCount();$('achievement-summary').textContent=`${earned} / 75 potion achievements earned. Reach a potion's maximum enhancement level to earn its unique title and lore.`;FAMILIES.forEach((f,i)=>{const b=document.createElement('button');b.textContent=f.label;b.className=i===achievementFamily?'active':'';b.onclick=()=>{achievementFamily=i;renderAchievements();};filters.append(b);});FAMILIES[achievementFamily].recipes.forEach((r,tier)=>{const id=achievementFamily+'-'+tier,record=game.state.metrics.recipes[id],level=record?.highestLevel||0,unlocked=level>=r.max_level,entry=ACHIEVEMENT_LORE.entries[id],card=document.createElement('article');card.className='achievement-card '+(unlocked?'earned':'locked');const image=document.createElement('img');image.src=art(r.image);image.alt='';const title=document.createElement('h3');title.textContent=entry.title;const desc=document.createElement('p');desc.className='achievement-lore';desc.textContent=entry.lore;const status=document.createElement('span');status.className='achievement-status';status.textContent=unlocked?'Earned':`Highest level ${level} / ${r.max_level}`;card.append(image,title,desc,status);grid.append(card);});}

const statisticSections=new Map();let statisticsDirty=true;
