 section('Requests and rewards',[['Request coins spent',fmt(s.requestCoinsSpent)+' G'],['Pushcat tickets',fmt(s.tickets)],['Likeability earned · aggregate',fmt(s.likeability)],['Request in progress',s.request?REQUESTS.find(r=>r.id===s.request.requestId).name:'None']]);
 section('Collections and upgrades',[['Potion types brewed',`${v.brewedTypes} / 75`],['Potion recipes unlocked',`${v.unlockedRecipes} / 75`],['Fairy types collected',`${v.fairyTypes} / ${FAIRIES.length}`],['Fairies received',fmt(v.fairiesReceived)],['Duplicate fairies',fmt(v.fairiesReceived-v.fairyTypes)],['Life material level',s.tiers[0]+1],['Mana material level',s.tiers[1]+1],['Stamina material level',s.tiers[2]+1],['Material Emission level',`${s.speed+1} / ${ECONOMY.upgrades.speed.max+1}`],['Enhancement upgrade bonus',`+${(s.luck*ECONOMY.upgrades.luck.bonusPerLevel*100).toFixed(4)} percentage points`],['Selling upgrade bonus',`+${s.price*ECONOMY.upgrades.price.bonusPerLevel*100}%`],['Total owned upgrade steps',v.upgradesOwned]]);
