function fairyEffectText(id,level=game.fairyLevel(id)||1){const preview=new PotionGame();preview.state.fairies[id]=level;const effects=preview.fairyEffects(id,1),parts=[],percent=v=>Number((v*100).toFixed(2));for(const[key,label]of [['enhancementChance','success chance'],['enhancementMultiplier','extra value across the full enhancement path'],['sellBonus','sale bonus'],['failureProtection','protection chance after a failed enhancement, without a protection charge'],['materialProbability','ingredient spawn weight']])effects[key]?.forEach((value,f)=>{if(value)parts.push(`${FAMILIES[f].label}: +${percent(value)}${key==='enhancementChance'?' percentage points':'%'} ${label}`);});if(effects.materialAmount)parts.push(`Added ingredient value: +${percent(effects.materialAmount)}%`);if(effects.questPrep)parts.push(`Visitor preparation time: +${percent(effects.questPrep)}% (${Number((QUEST_DURATION_MS/1000*(1+effects.questPrep)).toFixed(2))} seconds)`);if(effects.visitorDelay)parts.push(`Visitor wait: −${percent(effects.visitorDelay)}% (${Number((ECONOMY.visitors.waitMinMs/1000*(1-effects.visitorDelay)).toFixed(2))}–${Number((ECONOMY.visitors.waitMaxMs/1000*(1-effects.visitorDelay)).toFixed(2))} seconds)`);if(effects.requestDurationReduction)parts.push(`Request duration: −${percent(effects.requestDurationReduction)}%`);if(effects.pushcatSummonTime||effects.blackcatSummonChance)parts.push(`Inactive: Pushcat summon time −${percent(effects.pushcatSummonTime||0)}%; Blackcat summon chance +${percent(effects.blackcatSummonChance||0)}%. Timed Pushcat / Blackcat summoning is not implemented.`);return parts.join('\n')||'Inactive: no implemented ability in this game.';}

function renderFairies(){const counts=game.state.fairies,total=Object.values(counts).reduce((a,b)=>a+b,0),active=game.state.activeFairyId;$('fairy-summary').textContent=`${Object.keys(counts).length} / ${FAIRIES.length} fairy types · ${fmt(total)} received · ${active?FAIRIES.find(f=>f.id===active).name+' is active':'No fairy equipped'}`;
 const grid=$('fairy-grid');grid.replaceChildren();for(const f of FAIRIES){const count=counts[f.id]||0,level=game.fairyLevel(f.id),card=document.createElement('div');card.className='fairy-card '+(count?'owned':'locked')+(active===f.id?' equipped':'');const im=document.createElement('img');im.src=art(f.image);im.alt=f.name;const title=document.createElement('h3');title.textContent=f.name;const label=document.createElement('p');label.textContent=count?`Lv ${level} / 10 · received ×${fmt(count)}`:'Not collected yet · Lv 1 preview';const effect=document.createElement('p');effect.className='fairy-effect';effect.textContent=fairyEffectText(f.id);card.append(im,title,label,effect);if(level<10){const comparison=document.createElement('details'),summary=document.createElement('summary'),maximum=document.createElement('p');summary.textContent='At level 10';maximum.className='fairy-effect';maximum.textContent=fairyEffectText(f.id,10);comparison.append(summary,maximum);card.append(comparison);}if(count&&FAIRY_LABELS[f.id]){const button=document.createElement('button');button.textContent=active===f.id?'Unequip':'Equip';button.onclick=()=>{game.setActiveFairy(active===f.id?null:f.id);save();renderFairies();render();updateBeltLabels();};card.append(button);}grid.append(card);}}
