$('fairy-shortcut').onclick=()=>{$('equipped-fairy-dialog').showModal();};
function questTimerText(t){const now=Date.now(),seconds=time=>Math.max(0,Math.ceil((time-now)/1000));return t.phase==='offer'?`Leaves in ${seconds(t.leaveAt)}s · ${QUEST_DURATION_MS/1000} seconds to brew after accepting.`:t.phase==='active'?`Time left: ${seconds(t.deadline)}s`:t.phase==='returning'?`Reward arrives in ${seconds(t.readyAt)}s`:t.phase==='complete'?`Reward received · leaves in ${seconds(t.leaveAt)}s`:t.phase==='failed'?`Quest expired · potion kept · leaves in ${seconds(t.leaveAt)}s`:'';}

