function openEvent(index){eventPageIndex=index;eventPageSnapshot='';eventDialog.querySelector('.event-feedback').textContent='';refreshEventPage();eventDialog.showModal();}
function refreshEventPage(){
 const info=game.eventInfo(),event=EVENTS[eventPageIndex],current=eventPageIndex===info.index;
 eventDialog.querySelector('.event-page-status').textContent=current?eventStatusText(info):'Upcoming rotation · redemption opens when this event starts.';
 eventDialog.querySelector('.event-page-balance').textContent=fmt(info.solution)+' Miracle Solution saved';
 const snapshot=JSON.stringify([eventPageIndex,info.index,info.solution,game.state.costumes,game.state.tiaUnlocked,game.state.powerups]);if(snapshot===eventPageSnapshot)return;eventPageSnapshot=snapshot;
 eventDialog.querySelector('h2').textContent=event.name;const banner=eventDialog.querySelector('.event-page-banner');banner.src=art(event.banner);banner.alt=event.name+' banner';
 const rewards=eventDialog.querySelector('.event-rewards');rewards.replaceChildren();
 for(const id of [...event.skins,'boosts']){
  const costume=COSTUMES.entries.find(c=>c.id===id),owned=game.state.costumes.includes(id),locked=costume?.character==='Tia'&&!game.state.tiaUnlocked,cost=id==='boosts'?ECONOMY.events.boostCost:ECONOMY.events.skinCost,row=document.createElement('section'),image=document.createElement('img'),copy=document.createElement('div'),name=document.createElement('h3'),detail=document.createElement('p'),button=document.createElement('button');
  row.className='event-reward';image.src=art(costume?.id||'WikiPotion.png');image.alt='';name.textContent=costume?costume.character+' · '+costume.name:'Boost bundle';detail.className='small muted';detail.textContent=costume?ECONOMY.events.skinCost+' Miracle Solution':ECONOMY.events.boostCost+' Miracle Solution → '+Object.entries(ECONOMY.events.boostBundle).map(([key,amount])=>amount+' '+({protection:'failure protection',enhancement:'enhancement bonus',selling:'selling bonus'}[key])).join(' + ');copy.append(name,detail);
  const full=id==='boosts'&&Object.entries(ECONOMY.events.boostBundle).some(([key,amount])=>game.state.powerups[key]>1e9-amount);
  button.type='button';button.textContent=owned?'Owned':locked?'Unlock Tia first':!current?'Not active':full?'Boost storage full':'Redeem · '+cost;button.disabled=owned||locked||!current||full||info.solution<cost;
  button.onclick=()=>{if(!game.redeemEvent(eventPageIndex,id))return;save(true);render();eventDialog.querySelector('.event-feedback').textContent=costume?costume.name+' added to your wardrobe.':'Received one of each boost.';};row.append(image,copy,button);rewards.append(row);
 }
}
