const promotion=document.createElement('figure');promotion.innerHTML='<figcaption><h4>Season 2 · Archived promotion</h4><p>Original Twitter follow and retweet event. Outside the gameplay rotation.</p></figcaption>';const promotionImage=document.createElement('img');promotionImage.src=art('Third_Event_Banner_-_English.webp');promotionImage.alt='Season 2 follow and retweet promotion';promotionImage.loading='lazy';promotion.prepend(promotionImage);eventGallery.append(promotion);
function updateEventGallery(info){const key=info.index+'|'+info.active;if(updateEventGallery.key===key)return;updateEventGallery.key=key;const next=(info.index+1)%EVENTS.length;promotion.hidden=info.active;promotion.style.order='0';eventFigures.forEach((figure,index)=>{figure.hidden=index!==next&&(!info.active||index!==info.index);figure.style.order=index===next?'1':'0';figure.classList.toggle('current-event',info.active&&index===info.index);setText(figure.querySelector('h4'),(index===next?'Next · ':'Current · ')+EVENTS[index].name);});eventOpen.textContent=info.active?'View current event':'Redeem ending event';}
window.refreshEvents=()=>{const info=game.eventInfo();setText(eventClock,eventStatusText(info));setText(solutionCount,fmt(info.solution)+' Miracle Solution');updateEventGallery(info);if(!info.active&&conveyor?.items.some(m=>m.kind==='solution')){conveyor.items=conveyor.items.filter(m=>m.kind!=='solution');syncBelt();}if(eventDialog.open)refreshEventPage();};
