const rewardShop=document.createElement('div');rewardShop.className='reward-shop';
const rewardDialog=document.createElement('dialog');rewardDialog.id='reward-dialog';rewardDialog.setAttribute('aria-label','Shop reward');rewardDialog.innerHTML='<button class="close" aria-label="Close reward">×</button><h2></h2><p class="reward-odds small muted"></p><p class="reward-balance"></p><p class="reward-quota small"></p><div class="case-window"><div class="case-reel"></div></div><p class="reward-result" aria-live="polite"></p><button class="reward-free primary"></button><button class="reward-open primary"></button>';document.body.append(rewardDialog);rewardDialog.querySelector('.close').onclick=()=>rewardDialog.close();
let rewardKind='hourly',rewardBusy=false,rewardAnimation=null;
const rewardButtons={},rewardNames={hourly:'Boost chest',tickets:'Ticket case',skin:'Ruby case'},rewardLabels={tickets:'Pushcat tickets',rubies:'rubies',fairy:'fairy',skin:'skin',protection:'failure protection',enhancement:'enhancement boost',selling:'double-sale boost'};
function rewardOddsText(kind){const cost=game.rewardCost(kind),rules=ECONOMY.chests;if(kind==='hourly')return ` One free opening every ${duration(rules.freeBoostCooldownMs)}. Gold price follows your highest unlocked material tier. Up to ${rules.hourly.paidLimit} paid openings per ${rules.hourly.paidWindowMs/60000} active minutes; paid openings keep the free timer. Each opening awards one boost type.`;const expected=game.rewardExpectations(kind,window.brewerCharacter||'Pio'),parts=['tickets','rubies'].filter(key=>expected[key]>0).map(key=>Number(expected[key].toFixed(2))+' '+rewardLabels[key]),returned=Object.entries(expected).reduce((sum,[key,amount])=>sum+(CURRENCY_UNITS[key]?amount/CURRENCY_UNITS[key]:0),0),paid=cost.amount/CURRENCY_UNITS[cost.currency];return ` Average currency return: ${parts.join(' + ')} (${Number((returned/paid*100).toFixed(2))}% at Bank rates). Fairy and new-skin value excluded. Fairies below level 10 are equally likely; all maxed converts a fairy roll to ${rules.maxFairyTickets} tickets.`+(kind==='skin'?` Eligible current-character skins are equally likely; event skins are excluded. Duplicates convert to ${rules.duplicateTickets} tickets. Each opening has its own odds; no guaranteed skin after a fixed number of openings.`:'');}
function rewardArt(currency,name=''){if(currency==='skin')return game.state.activeCostumeId;if(currency==='fairy')return FAIRIES.find(f=>f.name===name)?.image||FAIRIES[0].image;return currency==='tickets'?'Nyan-Ticket.png':currency==='rubies'?'Gem.png':DATA.powerups[currency].image;}
function rewardDescription(result){return result.currency==='skin'?(result.name?'Unlocked '+result.name:'Random skin'):result.currency==='fairy'?(result.name||'Random fairy')+' ×1':(result.name?result.name+' → ':'')+result.amount+' '+rewardLabels[result.currency];}
for(const[kind,icon]of [['hourly','RewardIcon1.png'],['tickets','RewardIcon2.png'],['skin','RewardIconFairy.png']]){
 const button=document.createElement('button'),image=document.createElement('img'),title=document.createElement('span'),detail=document.createElement('small');image.src=art(icon);image.alt='';title.textContent=rewardNames[kind];button.append(image,title,detail);
 button.onclick=()=>{rewardKind=kind;rewardDialog.querySelector('h2').textContent=rewardNames[kind];rewardDialog.querySelector('.reward-result').textContent='';rewardDialog.querySelector('.case-reel').replaceChildren();const rows=game.rewardPool(kind),total=rows.reduce((n,r)=>n+r.weight,0);let odds=rows.map(r=>(100*r.weight/total).toFixed(2).replace(/\.00$/,'')+'%: '+r.amount+' '+rewardLabels[r.currency]).join(' · ');odds+=rewardOddsText(kind);rewardDialog.querySelector('.reward-odds').textContent=odds;updateRewardShop();rewardDialog.showModal();};rewardButtons[kind]={button,detail};rewardShop.append(button);
}
