const questMark=document.createElement('img');questMark.className='quest-mark';questMark.src=art('QuestMark.png');questMark.alt='';$('visitor-shortcut').append(questMark);
function updateRewardShop(){const s=game.state,quota=game.paidBoostInfo();for(const kind of ['hourly','tickets','skin']){const cost=game.rewardCost(kind);setText(rewardButtons[kind].detail,fmt(cost.amount)+' '+(cost.currency==='coins'?'gold':cost.currency));}setText(rewardDialog.querySelector('.reward-balance'),fmt(s.coins)+' gold · '+fmt(s.tickets)+' tickets · '+fmt(s.rubies)+' rubies');const button=rewardDialog.querySelector('.reward-open'),cost=game.rewardCost(rewardKind),noSkinPool=rewardKind==='skin'&&!game.eligibleSkins(window.brewerCharacter||'Pio').length;button.disabled=rewardBusy||s[cost.currency]<cost.amount||(rewardKind==='hourly'&&quota.remaining<1)||noSkinPool;setText(button,rewardBusy?'Opening…':noSkinPool?'No eligible skins':rewardKind==='hourly'&&quota.remaining<1?'Paid openings used':'Open · '+fmt(cost.amount)+' '+(cost.currency==='coins'?'gold':cost.currency));const freeButton=rewardDialog.querySelector('.reward-free'),remaining=Math.max(0,s.rewardReadyAt-Date.now());freeButton.hidden=rewardKind!=='hourly';freeButton.disabled=rewardBusy||remaining>0;setText(freeButton,rewardBusy?'Opening…':remaining?'Free in '+duration(remaining):'Open free');const gold=fmt(game.rewardCost('hourly').amount);setText(rewardButtons.hourly.detail,(remaining?gold+' gold · free in '+duration(remaining):'Free ready · or '+gold+' gold')+' · '+quota.remaining+' paid left');const note=rewardDialog.querySelector('.reward-quota');note.hidden=rewardKind!=='hourly';setText(note,`${quota.remaining} / ${quota.limit} paid openings left · refresh in ${duration(quota.remainingMs)} of active play`);if(rewardDialog.open){const rows=game.rewardPool(rewardKind),total=rows.reduce((n,r)=>n+r.weight,0);setText(rewardDialog.querySelector('.reward-odds'),rows.map(r=>Number((100*r.weight/total).toFixed(2))+'%: '+r.amount+' '+rewardLabels[r.currency]).join(' · ')+rewardOddsText(rewardKind));}}
async function openChest(free=false){
 if(rewardBusy)return;const result=game.openReward(rewardKind,window.brewerCharacter||'Pio',Date.now(),Math.random,free);if(!result)return;save(true);render();rewardBusy=true;updateRewardShop();
 const output=rewardDialog.querySelector('.reward-result'),reel=rewardDialog.querySelector('.case-reel');output.textContent='';reel.replaceChildren();rewardAnimation?.cancel();reel.style.transform='none';
 const pool=game.rewardPool(rewardKind),total=pool.reduce((n,r)=>n+r.weight,0);
 function previewReward(){let roll=Math.random()*total;for(const row of pool){if(roll<row.weight)return row;roll-=row.weight;}return pool[pool.length-1];}
 const cards=38;
 for(let i=0;i<cards;i++){const prize=cards===1||i===32?result:previewReward(),card=document.createElement('div'),image=document.createElement('img'),label=document.createElement('span');card.className='case-item';image.src=art(rewardArt(prize.currency,prize.name));image.alt='';label.textContent=rewardDescription(prize);card.append(image,label);reel.append(card);}
 if(cards>1){const target=rewardDialog.querySelector('.case-window').clientWidth/2-32*120-56;rewardAnimation=reel.animate([{transform:'translateX(0)'},{transform:'translateX('+target+'px)'}],{duration:reducedMotion?0:ECONOMY.chests.revealMs,easing:'cubic-bezier(.12,.72,.12,1)',fill:'forwards'});try{await rewardAnimation.finished;}catch{}}
 output.textContent='You received '+rewardDescription(result)+'!';rewardBusy=false;updateRewardShop();notice(output.textContent,'success');
};
rewardDialog.querySelector('.reward-open').onclick=()=>openChest();
rewardDialog.querySelector('.reward-free').onclick=()=>openChest(true);
rewardDialog.addEventListener('close',()=>{rewardAnimation?.finish();});
setInterval(updateRewardShop,1000);updateRewardShop();

// Browser preferences are separate from transferable gameplay saves.
function applyGameSettings(){reducedMotion=gameSettings.reducedMotion;const root=document.documentElement;root.dataset.reducedMotion=String(reducedMotion);root.dataset.shortcuts=String(gameSettings.shortcuts);root.dataset.textSize=gameSettings.textSize;if(music)music.volume=gameSettings.musicVolume;if(!gameSettings.idleDialogue)window.clearIdleDialogue?.();if(reducedMotion)rewardAnimation?.finish();}
for(const key of Object.keys(gameSettings)){const control=$('setting-'+key);control.type==='checkbox'?control.checked=gameSettings[key]:control.value=String(gameSettings[key]);control.oninput=()=>{gameSettings[key]=control.type==='checkbox'?control.checked:control.tagName==='SELECT'&&key==='textSize'?control.value:Number(control.value);applyGameSettings();try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(gameSettings));$('settings-message').textContent='Settings saved on this browser.';}catch{$('settings-message').textContent='Settings apply now, but could not be saved.';}};}
$('settings-save-now').onclick=()=>{$('save-now').click();$('settings-save-status').textContent=$('save-status').textContent;};$('settings-save-tools').onclick=()=>{gameMenu.close();$('save-dialog').showModal();};
new MutationObserver(()=>$('settings-save-status').textContent=$('save-status').textContent).observe($('save-status'),{childList:true,characterData:true,subtree:true});$('settings-save-status').textContent=$('save-status').textContent;
let effectAudio=null;document.addEventListener('click',event=>{if(!gameSettings.effectsVolume||!event.target.closest('button:not(:disabled)'))return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;effectAudio??=new Audio();if(effectAudio.state==='suspended')void effectAudio.resume().catch(()=>{});const oscillator=effectAudio.createOscillator(),gain=effectAudio.createGain(),now=effectAudio.currentTime;oscillator.frequency.value=660;gain.gain.setValueAtTime(gameSettings.effectsVolume*.08,now);gain.gain.exponentialRampToValueAtTime(.001,now+.06);oscillator.connect(gain);gain.connect(effectAudio.destination);oscillator.start(now);oscillator.stop(now+.06);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};}catch{}});
applyGameSettings();

function refreshMail(){const pending=UPDATES.entries.filter(update=>!game.state.claimedUpdates.includes(update.id));setText($('mail-count'),pending.length?pending.length+(pending.length===1?' gift':' gifts'):'Up to date');const key=JSON.stringify([game.state.claimedUpdates,saveBlocked,game.state.rubies]);if(refreshMail.key===key)return;refreshMail.key=key;const box=$('mail-updates');box.replaceChildren();for(const update of UPDATES.entries){const card=document.createElement('article'),date=document.createElement('small'),title=document.createElement('h4'),list=document.createElement('ul'),button=document.createElement('button'),icon=document.createElement('img'),claimed=game.state.claimedUpdates.includes(update.id);card.className='update-mail';date.textContent=update.date;title.textContent=update.title;for(const text of update.notes){const item=document.createElement('li');item.textContent=text;list.append(item);}button.type='button';button.disabled=claimed||saveBlocked;icon.src=art('Gem.png');icon.alt='';button.append(icon,claimed?'Claimed':saveBlocked?'Restore saving to claim':'Claim '+update.rubies+' rubies');button.onclick=()=>{const rubies=game.state.rubies,claims=[...game.state.claimedUpdates],reward=game.claimUpdate(update.id);if(reward===null)return;save(true);if(!saveOK||saveBlocked){game.state.rubies=rubies;game.state.claimedUpdates=claims;saveDirty=true;$('mail-status').textContent='Could not save your claim. Free up browser storage and try again.';refreshMail.key=null;refreshMail();return;}render();$('mail-status').textContent='Thank you for playing! Received '+reward+' rubies.';};card.append(date,title,list,button);box.append(card);}}
window.refreshMail=refreshMail;refreshMail();

function addMenuReturn(dialog){if(dialog.id==='game-menu'||dialog.querySelector('[data-back-to-menu]'))return;const button=document.createElement('button');button.type='button';button.className='back-to-menu';button.dataset.backToMenu='';button.textContent='← Back to menu';button.onclick=()=>{document.querySelectorAll('dialog[open]').forEach(open=>open.close());$('game-menu-open').click();};const close=dialog.querySelector('.close');if(close)close.after(button);else dialog.prepend(button);}
document.querySelectorAll('dialog').forEach(addMenuReturn);
new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes){if(node.nodeType===1&&node.matches('dialog'))addMenuReturn(node);}}).observe(document.body,{childList:true});
